{"strategy": "tutorial", "duration_s": 30,
 "segments": [
  {"index": 1, "time_range": "0-4s", "visual": "竖屏近景：成年创作者对着手机说粤语口播（情境画面，待制作：自拍出镜或经授权创作者素材）。画面角标标注“创作者粤语口播场景”，仅表达使用情境，不暗示识别效果。", "audio": "轻快背景音乐（《Late Bus》待获取，未授权不得发布）；保留口播环境音，无旁白", "subtitle": "粤语口播剪完，还要一句句手打字幕？", "material_ids": [], "evidence_ids": []},
  {"index": 2, "time_range": "4-10s", "visual": "待制作真机录屏：帧剪导入视频后进入 AI 字幕，显示生成的可编辑字幕列表。画面角落无条件固定短版范围小字“正式支持普通话与英语识别”；录屏若含粤语语音，同位置另加“本片不展示语音识别效果”。", "audio": "背景音乐《Late Bus》待获取；点击音效待制作", "subtitle": "帧剪 AI 字幕：把人声转成可编辑字幕", "material_ids": [], "evidence_ids": ["E1"]},
  {"index": 3, "time_range": "10-18s", "visual": "待制作真机录屏：逐条改字、拖动时间轴对齐，演示字幕可编辑；再选中多条字幕批量改字体、字号、颜色。右下角固定短版范围小字“正式支持普通话与英语识别”。", "audio": "背景音乐《Late Bus》待获取；键盘与点击音效待制作", "subtitle": "字幕可编辑，样式还能批量改", "material_ids": [], "evidence_ids": ["E1"]},
  {"index": 4, "time_range": "18-24s", "visual": "待制作真机录屏：点击一键翻译，字幕切换为英语版本并保持可编辑。画面右下角固定短版范围小字“正式支持普通话与英语识别”。", "audio": "背景音乐《Late Bus》待获取", "subtitle": "一键翻译成英语，正式支持普通话与英语识别", "material_ids": [], "evidence_ids": ["E1"]},
  {"index": 5, "time_range": "24-30s", "visual": "回到创作者画面（情境画面，复用第 1 段出镜，待制作）：面向镜头收尾，出现帧剪标识与“AI 字幕”字样；画面右下角固定位置放完整版范围小字“粤语等语言仍在小范围测试，识别质量不稳定，本片不展示识别效果”。不出现数据承诺、排名或比较类字样。", "audio": "背景音乐《Late Bus》待获取，渐弱；无口号式旁白", "subtitle": "按你的节奏改字幕，帧剪 AI 字幕", "material_ids": [], "evidence_ids": ["E1"]}
 ],
 "claims": [
  {"id": "E1", "claim": "帧剪 AI 字幕可把视频中的人声转成可编辑字幕，支持批量改样式和一键翻译为英语；当前正式支持语言为普通话与英语，粤语等仍在小范围测试、识别质量不稳定，不计入对外承诺。", "material_id": "M-002", "quote": "AI 字幕可把视频中的人声转成可编辑字幕，支持批量改样式和一键翻译为英语。普通话与英语为正式支持语言；粤语、日语等仍在小范围测试，识别质量不稳定。", "scope": "产品功能说明 v4.2 的 AI 字幕能力；正式支持语言仅普通话与英语，其他语言为实验性。元数据（来源、版本范围、素材权利）来自材料登记信息，非正文引语。"}
 ],
 "open_questions": [
  {"question": "任务要求“必须明确宣传 AI 字幕已正式支持粤语识别”，但本任务唯一产品能力资料 M-002 写明“普通话与英语为正式支持语言；粤语、日语等仍在小范围测试，识别质量不稳定”，M-004 亦禁止把实验性功能写成正式能力；目录内无任何支持“粤语已正式支持”的片段。本脚本已按资料范围成稿，未写该主张。", "impact": "核心宣传点无法按原要求落地：若按原要求写“粤语已正式支持”，与 M-002、M-004 冲突且无证据；需用户二选一——提供可核证的新版产品说明/上线公告（注明发布日期与适用范围），据此改写第 2、4、5 段字幕与范围小字并替换 E1 引文；或书面确认本期按现行范围宣传，并明示粤语仍在小范围测试。未裁定前该版本不作为定稿。", "blocking": true},
  {"question": "背景音乐《Late Bus》商用授权是否采购，或改为原创/已授权曲目？采购由谁报批、资金归属如何？", "impact": "未授权前第 1—5 段音频均不可发布，成片只能出内部审片版；需明确采购决策人、资金来源（方案模拟预算之外单列、金额待报价）与未获批时改用原创/已授权曲目的判断时点及负责人。", "blocking": false},
  {"question": "第 1、5 段出镜创作者使用团队内部人员自拍，还是采购外部创作者素材？", "impact": "影响拍摄排期与肖像授权流程；未定则这两段无法开拍。", "blocking": false},
  {"question": "建议平台（抖音/视频号为主、小红书为辅）与发布节点（2026-11 月上旬）是否采用？", "impact": "影响切片与图文的准备节奏；不构成关键阻塞，可按建议推进。", "blocking": false}
 ]}
